"""Byte vectors below were generated by the firmware C code (lib/pmems_core/src/vision_proto.c)."""
import unittest

from pmems_config.vision_link import CodeQ, TriggerParser, crc16_modbus, result_cam1, result_cam2

TRIG_CAM1_ID_0x1234 = bytes.fromhex("55AA1034129EDC0A")
TRIG_CAM2_ID_300 = bytes.fromhex("55AA112C0184D10A")
RESULT_CAM1_ID77_M12_50 = bytes.fromhex("AA55204D001EFB00C7510D0A")
RESULT_CAM2_ID300_DUP_GRADE3_LEN42 = bytes.fromhex("AA55212C01032A13F72F0D0A")


class VisionLinkTest(unittest.TestCase):
    def test_crc(self):
        self.assertEqual(crc16_modbus(b"123456789"), 0x4B37)

    def test_results_match_firmware(self):
        self.assertEqual(result_cam1(77, -12.50), RESULT_CAM1_ID77_M12_50)
        self.assertEqual(result_cam2(300, CodeQ.DUPLICATE, grade=3, data_len=42),
                         RESULT_CAM2_ID300_DUP_GRADE3_LEN42)

    def test_trigger_parser_with_noise_and_split_reads(self):
        p = TriggerParser()
        stream = b"\x00\x55" + TRIG_CAM1_ID_0x1234 + b"\xFF" + TRIG_CAM2_ID_300
        got = []
        for i in range(0, len(stream), 3):          # arrives in small chunks
            got += p.feed(stream[i:i + 3])
        self.assertEqual([(t.camera, t.can_id) for t in got], [(1, 0x1234), (2, 300)])

    def test_trigger_parser_rejects_bad_crc(self):
        p = TriggerParser()
        bad = bytearray(TRIG_CAM2_ID_300)
        bad[5] ^= 1
        self.assertEqual(p.feed(bytes(bad)), [])
        self.assertEqual(p.crc_errors, 1)
        self.assertEqual([t.can_id for t in p.feed(TRIG_CAM2_ID_300)], [300])


if __name__ == "__main__":
    unittest.main()
